 FROM jsonb_to_recordset('[{"district":"Thị xã Kiến Tường","name":"Nhà sách Thanh Thanh 2","address_line":"271–273 Hùng Vương, phường 3 cũ, thị xã Kiến Tường","category":"nha_sach","phone":"0763246353","tax_code":null,"source_key":"gmap:ChIJlQ4o_Wn7CjERxIqGnMtgMHw","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20Thanh%20Thanh%202%20Ki%E1%BA%BFn%20T%C6%B0%E1%BB%9Dng&query_place_id=ChIJlQ4o_Wn7CjERxIqGnMtgMHw","verification_note":"Đối chiếu Google Maps và danh sách điểm bán Thiên Long năm 2024. Chưa Sales ghé xác minh."},{"district":"Thị xã Kiến Tường","name":"Nhà sách Đồng Tháp Mười","address_line":"139 Lý Thường Kiệt, phường 1 cũ, thị xã Kiến Tường","category":"nha_sach","phone":"02723840840","tax_code":"1100112728021","source_key":"gmap:ChIJZ19PApz6CjERwnW8ZsK7D1c","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20%C4%90%E1%BB%93ng%20Th%C3%A1p%20M%C6%B0%E1%BB%9Di%20139%20L%C3%BD%20Th%C6%B0%E1%BB%9Dng%20Ki%E1%BB%87t%20Ki%E1%BA%BFn%20T%C6%B0%E1%BB%9Dng&query_place_id=ChIJZ19PApz6CjERwnW8ZsK7D1c","verification_note":"MST chi nhánh hiện hoạt động 1100112728-021; nguồn Maps có điện thoại khác 0272 3820 898 trên hồ sơ thuế. CẦN đối chiếu 2 số. Bản đồ hiện vẫn ghi Mộc Hóa nhưng địa chỉ hành chính cũ là TX Kiến Tường, không xếp huyện Mộc Hóa."},{"district":"Thị xã Kiến Tường","name":"Văn phòng phẩm Xuân Nhi","address_line":"11 Hùng Vương, khu vực phường 1 cũ, thị xã Kiến Tường","category":"van_phong_pham","phone":"02723841991","tax_code":null,"source_key":"gmap:ChIJC7IG4eT6CjERK65jdVpMlAg","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Xu%C3%A2n%20Nhi%2011%20H%C3%B9ng%20V%C6%B0%C6%A1ng%20Ki%E1%BA%BFn%20T%C6%B0%E1%BB%9Dng&query_place_id=ChIJC7IG4eT6CjERK65jdVpMlAg","verification_note":"Một số nguồn dùng Mộc Hóa do tên huyện lịch sử; địa chỉ tuyến Hùng Vương thuộc đô thị Kiến Tường. Cần xác minh phường cũ."},{"district":"Thị xã Kiến Tường","name":"Văn