":null,"source_key":"gmap:ChIJxS6zfVHvCjERGXrtgiklsdo","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20H%C3%B9ng%20T%E1%BB%9Bi%20M%E1%BB%99c%20H%C3%B3a&query_place_id=ChIJxS6zfVHvCjERGXrtgiklsdo","verification_note":"Nguồn Maps có Plus Code, chưa xác định chắc xã cũ hoặc số nhà. Gắn nhãn cần kiểm tra vị trí."},{"district":"Huyện Mộc Hóa","name":"Văn phòng phẩm Nhớ","address_line":"Đường Võ Thị Tám, khu vực Mộc Hóa cũ (chưa có số nhà)","category":"van_phong_pham","phone":"0839273637","tax_code":null,"source_key":"gmap:ChIJ14ekGazvCjERJgZ6J9FUYEg","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Nh%E1%BB%9B%20V%C3%B5%20Th%E1%BB%8B%20T%C3%A1m%20M%E1%BB%99c%20H%C3%B3a&query_place_id=ChIJ14ekGazvCjERJgZ6J9FUYEg","verification_note":"Dữ liệu Maps ghi danh mục dress store nhưng tên VPP; cần xác minh có thực sự kinh doanh VPP và ranh giới huyện cũ."},{"district":"Huyện Tân Thạnh","name":"Nhà sách Tường Vy","address_line":"179 Quốc lộ 62, thị trấn Tân Thạnh cũ, huyện Tân Thạnh","category":"nha_sach","phone":"0365559262","tax_code":null,"source_key":"gmap:ChIJwzQz7mPsCjER2PODHAwGTB0","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20T%C6%B0%E1%BB%9Dng%20Vy%20179%20QL62%20T%C3%A2n%20Th%E1%BA%A1nh&query_place_id=ChIJwzQz7mPsCjER2PODHAwGTB0","verification_note":"Dữ liệu Maps xếp quà tặng, review/danh bạ ghi Nhà sách; cần Sales xác minh tại quầy."},{"district":"Huyện Tân Thạnh","name":"Nhà sách Kiến Chánh","address_line":"Quốc lộ 62, thị trấn Tân Thạnh cũ, huyện Tân Thạnh (Plus Code J26W+FWV)","category":"nha_sach","phone":"0919395061","tax_code":null,"source_key":"gmap:ChIJlXcT8WPsCjERzIoZGHLqSg4","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20Ki%E1%BA%BFn%20Ch%C3%A1nh%20T%C3%A2n%20Th%E1%BA%A1nh%20QL62&query_place_id=ChIJlXcT8WPsCjERzIoZGHLqSg4","verification_note":"Có Place ID khác Tường Vy; chưa có số nhà, không tự gộp."},{"district":"Huyện Tân Thạnh","name":"Văn phòng phẩm Gia Nhi","address_line":"287 ấp Kinh Nhà Thờ, xã Tân Lập cũ, huyện Tân Thạnh","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"thienlong:longan:gia-nhi:287-tanlap","source_url":"https://thienlonggroup.com/news/don-long-khi-vuot-long-mon-cac-nha-sach-thuc-hien","verification_note":"Danh sách cửa hàng thực hiện khuyến mại Thiên Long 19/04/2024, địa chỉ rõ. Cần gọi/xác minh hiện còn bán tại địa chỉ."},{"district":"Huyện Tân Hưng","name":"Nhà sách Công Lý","address_line":"Khu vực thị trấn Tân Hưng cũ, huyện Tân Hưng (chưa rõ số nhà)","category":"nha_sach","phone":"02723861386","tax_code":null,"source_key":"vietbiz:cong-ly:tan-hung","source_url":"https://www.viet-biz.com/nh%C3%A0-s%C3%A1ch-c%C3%B4ng-l%C3%BD-0272-3861-386","verification_note":"Danh bạ có tên và số điện thoại, chưa đủ số nhà, cần Sales gọi xác minh."},{"district":"Huyện Tân Hưng","name":"Nhà sách Hải Liên","address_line":"Đường 30/4, khu phố Gò Thuyền, thị trấn Tân Hưng cũ, huyện Tân Hưng","category":"nha_sach","phone":"0913980780","tax_code":"1100579128","source_key":"tax:1100579128:hai-lien","source_url":"https://thuvienphapluat.vn/ma-so-thue/ho-kinh-doanh-nha-sach-hai-lien-mst-1100579128.html","verification_note":"Có hồ sơ hộ kinh doanh + danh bạ tên nhà sách; chưa xác minh hoạt động thực tế. Khác với Nhà sách Tân Hưng LABOCO MST 1100112728-018 đã chấm dứt."},{"district":"Huyện Vĩnh Hưng","name":"Văn phòng phẩm Hồng Gấm","address_line":"75 Cách Mạng Tháng Tám, khu phố Bầu Sậy, thị trấn Vĩnh Hưng cũ, huyện Vĩnh Hưng","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"thienlong:longan:hong-gam:75-cmt8","source_url":"https://thienlonggroup.com/news/don-long-khi-vuot-long-mon-cac-nha-sach-thuc-hien","verification_note":"Có trong danh sách điểm bán Thiên Long 19/04/2024. Chưa xác minh còn cửa hàng đang mở."},{"district":"Huyện Vĩnh Hưng","name":"Công ty TNHH Mai Văn Tạo (đầu mối sách - VPP)","address_line":"59 ấp Thái Quang, xã Thái Trị cũ, huyện Vĩnh Hưng","category":"van_phong_pham","phone":null,"tax_code":"1102023329","source_key":"tax:1102023329:mai-van-tao","source_url":"https://chogia.vn/ma-so-thue/doanh-nghiep/1102023329","verification_note":"Đăng ký kinh doanh sách/báo/VPP theo dạng bán buôn; chưa có bằng chứng quầy bán lẻ, không coi là đã xác minh cửa hàng. Ưu tiên Sales gọi hỏi trước."}]'::jsonb) AS x(
 district text,name text,address_line text,category text,phone text,tax_code text,
 source_key text,source_url text,verification_note text)
), ins AS(
 INSERT INTO public.field_prospects(
 id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,note,
 status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT
 (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',
 s.name,s.address_line,'Long An',s.district,s.category,s.phone,s.tax_code,
 'Nghiên cứu nguồn công khai 21/11/2026. CHƯA GHÉ, GPS chưa xác minh. '||s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-long-an-old-wave-03-five-districts'
 FROM src s
 WHERE s.district IN ('Thị xã Kiến Tường','Huyện Mộc Hóa','Huyện Tân Thạnh','Huyện Tân Hưng','Huyện Vĩnh Hưng')
  AND s.source_url LIKE 'https://%'
  AND NOT EXISTS(
  SELECT 1 FROM public.customers c WHERE c.province='Long An' AND c.district=s.district
   AND lower(btrim(c.name))=lower(btrim(s.name)))
  AND NOT EXISTS(
  SELECT 1 FROM public.field_prospects p WHERE p.province='Long An' AND p.district=s.district
   AND (p.research_source_key=s.source_key OR
   (lower(btrim(p.name))=lower(btrim(s.name)) AND lower(btrim(p.address_line))=lower(btrim(s.address_line)))))
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING district,name,phone,tax_code,category
)
SELECT district,count(*)::int inserted,
 count(*) FILTER(WHERE phone IS NOT NULL)::int phones,
 count(*) FILTER(WHERE tax_code IS NOT NULL)::int taxes,
 count(*) FILTER(WHERE category='nha_sach')::int bookstores,
 count(*) FILTER(WHERE category='van_phong_pham')::int stationery
FROM ins GROUP BY district ORDER BY district;